function dateTime(x:string){return new Date(x).toLocaleString('en-PH',{timeZone:'Asia/Manila',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
function makeIncident(db:Database,user:User,date:string,type:Incident['type'],detail:string,entryId?:string):Database{
 if(db.incidents.some(i=>i.userId===user.id&&i.date===date&&i.type===type&&(!entryId||i.entryId===entryId)))return db;
 const i:Incident={id:uid(),branch:user.branch,userId:user.id,date,type,detail,status:'Required',explanation:'',createdAt:new Date().toISOString(),entryId};
 return log({...db,incidents:[i,...db.incidents]},'system','Mandatory report created',`${type} · ${BRANCH_NAME(user.branch)} · ${date}`);
}
function enforceLoginDeadlines(db:Database,user:User):Database{
 if(user.role!=='cashier')return db;
 let out=db;const today=todayPH();
 if(user.lastLoginDate&&user.lastLoginDate<today){const wasClosed=out.counts.some(c=>c.userId===user.id&&c.date===user.lastLoginDate&&c.kind==='EOD');
  if(!wasClosed)out=makeIncident(out,user,user.lastLoginDate,'Missed Closing',`No Closing Cash Count recorded for ${datePH(user.lastLoginDate)}. An explanation is mandatory before entering transactions.`);
  if(!out.turnovers.some(t=>t.branch===user.branch&&t.date===user.lastLoginDate&&(t.kind||'Sales')==='Sales'))out=makeIncident(out,user,user.lastLoginDate,'Missed Sales Turnover',`Daily Sales Turnover was not submitted for ${datePH(user.lastLoginDate)}.`);}
 if(hourPH()>=9&&!out.counts.some(c=>c.userId===user.id&&c.date===today&&c.kind==='BOD'))
   out=makeIncident(out,user,today,'Missed Opening',`Opening Cash Count was not completed by 9:00 AM on ${datePH(today)}.`);
 return out;
}
function expectedCount(db:Database,branch:BranchId,kind:'BOD'|'EOD',date:string):number|null{
 const prior=db.counts.filter(c=>c.branch===branch&&c.kind==='EOD'&&c.date<date).sort((a,b)=>b.date.localeCompare(a.date))[0];
 if(kind==='BOD')return prior?.actual??null;
 const opening=db.counts.find(c=>c.branch===branch&&c.kind==='BOD'&&c.date===date);
 if(!opening)return null;
 const cashPayments=db.pos.filter(p=>p.branch===branch&&p.date===date).flatMap(p=>p.payments).filter(p=>p.mode==='Cash').reduce((n,p)=>n+p.amount,0);
 const turnovers=db.turnovers.filter(t=>t.branch===branch&&t.date===date&&(t.kind||'Sales')==='Sales').reduce((n,t)=>n+t.amount,0);
 return opening.actual+cashPayments-turnovers;
}
function Chartbars({values}:{values:number[]}){const max=Math.max(...values,1);return <div className="chartbars" aria-label="Recent transaction values">{values.map((v,i)=><div key={i} style={{height:`${Math.max(8,100*v/max)}%`}} title={pesos(v)}/>)}</div>}
