 function restoreBackupBeforeSetup(file?:File){
  if(!file||db.users.length)return;
  file.text().then(async text=>{
   try{
    const parsed=JSON.parse(text) as Database|{backupType:string;database:Database;studioFiles:unknown};
    const full=!!parsed&&typeof parsed==='object'&&'backupType' in parsed&&parsed.backupType==='UC-CASHIER-LOCAL';
    const restored:Database=full?(parsed as {database:Database}).database:parsed as Database;
    if(!restored||!Array.isArray(restored.users)||!Array.isArray(restored.pos)||!Array.isArray(restored.fundEntries)||!Array.isArray(restored.audit)||!restored.settings?.rfBase)throw new Error('This is not a valid Cashier System backup.');
    if(!restored.users.some(u=>u.role==='admin'&&u.active))throw new Error('The backup has no active Admin login. It cannot restore your access.');
    if(full&&!Array.isArray((parsed as {studioFiles:unknown}).studioFiles))throw new Error('Backup is missing its Docs/Sheets files.');
    if(!await confirmAction('Restore the selected account/database backup? This REPLACES data in the current browser. If records are still present, export them first. Full backups also replace local Docs/Sheets.'))return;
    const previousDB=localStorage.getItem(STORAGE_KEY);
    const previousOffice=localStorage.getItem(STUDIO_KEY);
    try{
     // Only commit the new data after confirming the current browser can store it.
     if(full)localStorage.setItem(STUDIO_KEY,JSON.stringify((parsed as {studioFiles:unknown}).studioFiles));
     if(!storeDB(restored))throw new Error('Browser storage could not save the backup.');
    }catch{
     if(previousDB===null)localStorage.removeItem(STORAGE_KEY);else localStorage.setItem(STORAGE_KEY,previousDB);
     if(previousOffice===null)localStorage.removeItem(STUDIO_KEY);else localStorage.setItem(STUDIO_KEY,previousOffice);
     throw new Error('Browser storage is full or blocked; restore was cancelled.');
    }
    setDB(restored);setSession('');sessionStorage.removeItem('uc_fund_session');
    notify('Backup restored. Sign in using the existing account from your backup.');
   }catch(error){notify((error as Error).message||'Backup could not be restored.');}
  }).catch(()=>notify('Could not read the selected backup file.'));
 }
