  update(old=>{let next={...old,counts:[c,...old.counts]};if(difference!==0)next=makeIncident(next,user,date,'Cash Discrepancy',`${countKind}: expected ${pesos(expected)}, counted ${pesos(actual)} (${pesos(difference)} variance).`);return log(next,user.id,`${countKind} cash count`,`${pesos(actual)} · variance ${pesos(difference)}`)});
  setDialog(null);notify(difference!==0?'Cash count saved. A discrepancy explanation is required.':`${countKind} recorded successfully.`);
