  const now=new Date().toISOString();
  const draft:POS={id:uid(),no:nextNumber(db,currentBranch,'POS'),branch:currentBranch,date:pForm.date,client:pForm.client.trim(),phone:pForm.phone,vehicle:vehicleName(CAR_CATALOG.find(v=>v.toLowerCase()===pForm.vehicle.trim().toLowerCase())||pForm.vehicle,pForm.vehicleYear),plate:normalizePlate(pForm.plate),concern:pForm.concern,serviceType:pForm.serviceType,items:wizardLines,payments:[],status:'Pending',createdBy:user.id,createdAt:now};
