 async function savePOSDraft(continueToPayment=false){
  if(!user||!validPOSVehicle()||locked)return;
  const issue=quotationIssue(quotationRows,db.inventory,currentBranch);if(issue){notify(issue);return;}
  const lines=wizardLines;const issues=costReviewIssues(lines);if(issues.length){notify(issues[0]);return;}
  const decision=unitVisitDecision(db,pForm.plate,currentBranch);
  if(decision.kind==='blocked'||decision.kind==='conflict'){notify(decision.reason||'Active unit conflict.');return;}
  const previous=decision.visit;
  if(editingPOSId&&db.pos.find(x=>x.id===editingPOSId)?.plate!==normalizePlate(pForm.plate)){notify('An existing draft cannot be reassigned to a different plate. Finish this draft or open another unit.');return;}
  if(previous&&editingPOSId&&editingPOSId!==previous.id){notify('Draft ownership changed. Reload the unit before saving.');return;}
  if(previous){const reason=cannotReviseDraft(db,previous);if(reason){notify(reason);return;}}
  const now=new Date().toISOString();const no=previous?.no||nextNumber(db,currentBranch,'POS');
  const p:POS={id:previous?.id||uid(),no,quotationPhase:continueToPayment?'Final':previous?.quotationPhase||'Final',firstQuotation:previous?.firstQuotation,branch:currentBranch,date:pForm.date,client:pForm.client.trim(),phone:pForm.phone,vehicle:vehicleName(CAR_CATALOG.find(v=>v.toLowerCase()===pForm.vehicle.trim().toLowerCase())||pForm.vehicle,pForm.vehicleYear),plate:normalizePlate(pForm.plate),concern:pForm.concern,serviceType:pForm.serviceType,items:lines,payments:previous?.payments||[],cogsReviewedAt:now,cogsReviewedBy:user.id,status:'Pending',createdBy:previous?.createdBy||user.id,createdAt:previous?.createdAt||now};
  if(previous?.payments.length&&posTotal(p)+0.005<paidTotal(previous)){notify(`Sale total cannot be less than the ${pesos(paidTotal(previous))} already received. Increase the revised total or use an authorized refund workflow.`);return;}
  if(!await confirmAction(`${previous?'Update existing':'Save new'} draft ${no}?\nUnit: ${p.plate}\n${lines.length} quotation row(s)\nSale Total: ${pesos(posTotal(p))}\n\n${previous?'Changes will be recorded in Draft History. This will NOT create another POS.':'Proceed to Cash / Terminal / QR payment.'}`))return;
  try{const result=saveUnitPOSDraft(db,p,user.id);const next=result.created?linkPartsOnSale(result.db,result.pos):result.db;
   update(()=>next);setRecordId(result.pos.id);setEditingPOSId('');setWizardLines([]);setQuotationRows([emptyQuotationRow(uid())]);clearWizardEditor();if(continueToPayment){setPosStep(5);setPosFlow('final');setDialog('posCreate');}else{setDialog('posRecord');setPosStep(1);setPosFlow('standard');}
   notify(result.created?`Draft ${result.pos.no} created.`:result.changed?`Draft ${result.pos.no} updated; Draft History saved.`:`Draft ${result.pos.no} already up to date.`);
  }catch(err){notify((err as Error).message);}
 }

