 function requestEdit(item:FundEntry){if(db.requests.some(r=>r.entryId===item.id&&r.status==='Pending')){notify('A correction is already pending for this transaction.');return;}setRecordId(item.id);setEditSupplier(item.payee);setEditDescription(item.description);setEditPlate(item.plate||'');setEditQty(String(item.quantity||1));setEditPrice(String(item.unitCost||0));setEditReason('');openDialog('requestEdit',item.id)}
