 async function clearAllAppLocalStorage(){
  if(user?.role!=='admin')return;
  const keyword=window.prompt('DANGER: DELETE ALL LOCAL CASHIER DATA, user accounts, POS, inventory, audit history, AND Docs/Sheets saved in THIS browser. This cannot be undone. Export your complete backup first.\n\nType CLEAR ALL to continue:');
  if(keyword!=='CLEAR ALL')return;
  if(!await confirmAction('FINAL CONFIRMATION\n\nPermanently clear ALL Cashier System browser-local records AND saved Documents/Spreadsheets? You will be signed out and need to create a new administrator.'))return;
  try{
   clearCashierStorage(localStorage,sessionStorage);
   // A reload stops state persistence from rewriting records immediately after clearing.
   window.location.replace('/');
  }catch{notify('Unable to clear browser storage. Check browser permissions and retry.');}
 }
